#include <atomic>
#include <chrono>
#include <condition_variable>
#include <mutex>
#include <thread>
#include <vector>
#include "queue.h"

//==========================================
// DOWNLOADS MODULE (HOA 5 queue + threads)
// "Install" a game from the library. Downloads wait in a FIFO queue and ONE worker thread installs them
// one after another, like the Steam download queue. The install is a simulation: the worker only waits
// and counts progress, no real files are copied.
//
//   enqueue() puts a game in line         the worker takes the oldest waiting game
//   progress is 0..100 and is read by the screen while the worker is running
//   finished games are reported through takeFinished(), the caller marks them installed
//
// Thread safety: one mutex protects the queue and the job lists, a condition variable wakes the worker
// when there is work, and std::atomic holds the progress so the screen can read it without the mutex.
//==========================================

struct DownloadJob {
    int gameId = 0;
    int sizeMb = 0;
};

class DownloadManager {
private:
    LinkedQueue<DownloadJob> waiting;
    std::vector<int> finished;                  // finished and not yet collected with takeFinished()
    std::vector<int> waitingIds;                // same games as the queue, to show the line without touching the queue
    std::mutex lock;
    std::condition_variable wake;
    std::thread worker;
    std::atomic<bool> stopping;
    std::atomic<int> activeGameId;              // 0 = idle
    std::atomic<int> progress;                  // 0..100 of the active game
    int stepMs;                                 // milliseconds per 1% (smaller = faster, for tests)

//--- DownloadManager::run -------------------------------------------------------------------------
// What    : The worker thread: waits on the condition variable for a job, takes the oldest one from
//           the queue, and counts its progress from 1 to 100%. Bigger games take longer.
// Used by : DownloadManager::DownloadManager
//--------------------------------------------------------------------------------------------------
    void run() {
        while (true) {
            DownloadJob job;
            {
                std::unique_lock<std::mutex> guard(lock);
                wake.wait(guard, [this] { return stopping.load() || !waiting.empty(); });
                if (stopping.load()) return;
                waiting.dequeue(job);
                for (size_t i = 0; i < waitingIds.size(); i++) {
                    if (waitingIds[i] == job.gameId) { waitingIds.erase(waitingIds.begin() + (long)i); break; }
                }
                activeGameId = job.gameId;
                progress = 0;
            }
            // bigger games take longer: a minimum of 1 ms per percent, sizeMb scales it
            for (int p = 1; p <= 100 && !stopping.load(); p++) {
                int delay = stepMs + job.sizeMb / 400;
                std::this_thread::sleep_for(std::chrono::milliseconds(delay));
                progress = p;
            }
            std::lock_guard<std::mutex> guard(lock);
            if (progress.load() == 100) finished.push_back(job.gameId);
            activeGameId = 0;
            progress = 0;
        }
    }

public:
//--- DownloadManager::DownloadManager -------------------------------------------------------------
// What    : Creates the manager and starts the worker thread. msPerPercent sets the speed (small
//           values make tests fast).
// Used by : doShowcase (screens.h), initStore (store.h), tests (tests/test_dl.cpp)
//--------------------------------------------------------------------------------------------------
    explicit DownloadManager(int msPerPercent = 30)
        : stopping(false), activeGameId(0), progress(0), stepMs(msPerPercent) {
        worker = std::thread(&DownloadManager::run, this);
    }

//--- DownloadManager::~DownloadManager ------------------------------------------------------------
// What    : Sets the stop flag, wakes the worker and joins it, so the program never ends with a
//           running thread.
// Used by : runs by itself when the object goes out of scope or is deleted
//--------------------------------------------------------------------------------------------------
    ~DownloadManager() {
        stopping = true;
        wake.notify_all();
        if (worker.joinable()) worker.join();
    }

    DownloadManager(const DownloadManager&) = delete;
    DownloadManager& operator=(const DownloadManager&) = delete;

    // false when this game is already downloading or waiting
//--- DownloadManager::enqueue ---------------------------------------------------------------------
// What    : Puts a game at the end of the download queue and wakes the worker.
// Returns : false when the game is already downloading or waiting
// Used by : doDownloads (screens.h), doShowcase (screens.h), tests (tests/test_dl.cpp)
//--------------------------------------------------------------------------------------------------
    bool enqueue(int gameId, int sizeMb) {
        std::lock_guard<std::mutex> guard(lock);
        if (activeGameId.load() == gameId) return false;
        for (size_t i = 0; i < waitingIds.size(); i++) if (waitingIds[i] == gameId) return false;
        waiting.enqueue(DownloadJob{gameId, sizeMb});
        waitingIds.push_back(gameId);
        wake.notify_one();
        return true;
    }

//--- DownloadManager::activeId --------------------------------------------------------------------
// What    : The game that is being installed (atomic read).
// Returns : the game id, 0 when idle
// Used by : doDownloads (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
    int activeId() const { return activeGameId.load(); }
//--- DownloadManager::activeProgress --------------------------------------------------------------
// What    : Progress of the active download, 0 to 100 (atomic read).
// Returns : the percent
// Used by : doDownloads (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
    int activeProgress() const { return progress.load(); }

    // the games waiting behind the active one, in the order they will be installed
//--- DownloadManager::waitingList -----------------------------------------------------------------
// What    : The games waiting behind the active one, in install order.
// Returns : the game ids
// Used by : doDownloads (screens.h)
//--------------------------------------------------------------------------------------------------
    std::vector<int> waitingList() {
        std::lock_guard<std::mutex> guard(lock);
        return waitingIds;
    }

    // the games that finished since the last call
//--- DownloadManager::takeFinished ----------------------------------------------------------------
// What    : Hands over the games that finished since the last call, so the screen can mark them
//           installed.
// Returns : the game ids
// Used by : doDownloads (screens.h), doShowcase (screens.h), tests (tests/test_dl.cpp)
//--------------------------------------------------------------------------------------------------
    std::vector<int> takeFinished() {
        std::lock_guard<std::mutex> guard(lock);
        std::vector<int> out = finished;
        finished.clear();
        return out;
    }

//--- DownloadManager::idle ------------------------------------------------------------------------
// What    : Tells if nothing is running and nothing is waiting.
// Returns : true when idle
// Used by : tests (tests/test_dl.cpp)
//--------------------------------------------------------------------------------------------------
    bool idle() {
        std::lock_guard<std::mutex> guard(lock);
        return activeGameId.load() == 0 && waiting.empty();
    }
};

#endif //STEAM_DOWNLOADS_H
